    function borrowETH(
        address wallet,
        uint256 amount,
        uint256 interestRateMode
    ) external view returns (PluginExecution[] memory, bytes memory);

    function repay(
        address wallet,
        address asset,
        uint256 amount,
        uint256 interestRateMode
    ) external view returns (PluginExecution[] memory, bytes memory);

    function repayETH(
        address wallet,
        uint256 amount,
        uint256 interestRateMode
    ) external view returns (PluginExecution[] memory, bytes memory);

    function supplyPercentageOfBalance(
        address wallet,
        address asset,
        uint256 percentage
    ) external view returns (PluginExecution[] memory, bytes memory);

    function supplyPercentageOfBalanceETH(
        address wallet,
        uint256 percentage
    ) external view returns (PluginExecution[] memory, bytes memory);

    function changeSupplyToHealthFactorETH(
        address wallet,
        uint256 targetHealthFactor
    ) external view returns (PluginExecution[] memory, bytes memory);

    function changeSupplyToHealthFactor(
        address wallet,
