    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    IUniswapV3Zapper public immutable zapper;

    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃       Constructor         ┃
